<template>
	<view class="album-page">
		<view class="fixed-header album-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="nav-side">
					<view class="nav-action" @click="goBack">
						<image class="back-icon" src="/static/fanhui.png" mode="aspectFit" />
					</view>
				</view>
				<text class="nav-title">我的相册</text>
				<view class="nav-side is-right" />
			</view>
		</view>

		<view class="album-body" :style="{ paddingTop: headerTotalHeight + 'px' }">
			<view class="album-tools">
				<view class="album-summary">
					<text class="summary-title">全部照片</text>
					<text class="summary-count">{{ albumItems.length }} 张 · 手动上传 {{ manualCount }}/{{ manualLimit }}</text>
				</view>
				<view class="tool-actions">
					<view
						v-if="albumItems.length"
						class="manage-action"
						:class="{ active: managing, disabled: saving || uploading }"
						@click="toggleManage"
					>
						<text>{{ managing ? (saving ? '保存中' : '完成') : '管理' }}</text>
					</view>
					<view
						class="upload-action"
						:class="{ disabled: !canUpload }"
						@click="choosePhotos"
					>
						<text class="upload-icon">+</text>
						<text>{{ uploading ? '上传中' : '上传照片' }}</text>
					</view>
				</view>
			</view>

			<view v-if="loading && !albumItems.length" class="state-box">
				<text class="state-text">正在整理照片...</text>
			</view>
			<view v-else-if="!albumItems.length" class="state-box">
				<image class="empty-image" src="/static/empty.png" mode="aspectFit" />
				<text class="state-title">相册还是空的</text>
				<text class="state-copy">发布图片动态，或上传喜欢的照片</text>
			</view>
			<view v-else class="album-grid">
				<view
					v-for="(item, index) in albumItems"
					:key="item.key"
					class="album-item"
					:class="{ managing }"
					@click="handlePhotoClick(index)"
				>
					<image class="album-image" :src="item.thumbnailUrl || item.url" mode="aspectFill" lazy-load />
					<view v-if="managing" class="manage-shade">
						<text class="position-index">{{ index + 1 }}</text>
						<view
							v-if="item.type === 'manual'"
							class="delete-action"
							@click.stop="confirmDelete(item)"
						>
							<text>×</text>
						</view>
						<view class="move-actions">
							<view
								class="move-action"
								:class="{ disabled: index === 0 }"
								@click.stop="movePhoto(index, -1)"
							>
								<text>‹</text>
							</view>
							<view
								class="move-action"
								:class="{ disabled: index === albumItems.length - 1 }"
								@click.stop="movePhoto(index, 1)"
							>
								<text>›</text>
							</view>
						</view>
					</view>
				</view>
			</view>
		</view>
	</view>
</template>

<script>
import {
	addAlbumPhotos,
	deleteAlbumPhoto,
	fetchMyAlbum,
	updateAlbumOrder
} from '../../api/album';
import { uploadImage } from '../../utils/request';
import { showRequestError } from '../../utils/feedback';

export default {
	data() {
		return {
			loading: false,
			uploading: false,
			saving: false,
			managing: false,
			orderDirty: false,
			statusBarHeight: 44,
			headerTotalHeight: 96,
			albumItems: [],
			manualCount: 0,
			manualLimit: 9
		};
	},
	computed: {
		canUpload() {
			return !this.loading && !this.uploading && !this.saving && !this.managing && this.manualCount < this.manualLimit;
		}
	},
	onLoad() {
		this.setHeaderLayout();
		this.loadAlbum();
	},
	onPullDownRefresh() {
		if (this.managing) {
			uni.stopPullDownRefresh();
			return;
		}
		this.loadAlbum().finally(() => uni.stopPullDownRefresh());
	},
	methods: {
		setHeaderLayout() {
			try {
				const systemInfo = uni.getSystemInfoSync();
				this.statusBarHeight = systemInfo.statusBarHeight || 44;
				const rpxToPx = (systemInfo.windowWidth || 375) / 750;
				this.headerTotalHeight = this.statusBarHeight + Math.round(92 * rpxToPx);
			} catch (error) {
				this.statusBarHeight = 44;
				this.headerTotalHeight = 96;
			}
		},
		applyAlbum(result = {}) {
			this.albumItems = (Array.isArray(result.items) ? result.items : [])
				.filter((item) => item && item.key && item.url)
				.map((item) => ({
					...item,
					thumbnailUrl: item.thumbnailUrl || item.url
				}));
			this.manualCount = Number(result.manualCount || 0);
			this.manualLimit = Number(result.manualLimit || 9);
			this.orderDirty = false;
		},
		async loadAlbum() {
			if (this.loading) return;
			this.loading = true;
			try {
				this.applyAlbum(await fetchMyAlbum());
			} catch (error) {
				showRequestError(error, '相册加载失败');
			} finally {
				this.loading = false;
			}
		},
		async choosePhotos() {
			if (!this.canUpload) {
				if (this.manualCount >= this.manualLimit) {
					uni.showToast({ title: `最多上传 ${this.manualLimit} 张`, icon: 'none' });
				}
				return;
			}

			const remaining = this.manualLimit - this.manualCount;
			let paths = [];
			try {
				const result = await uni.chooseImage({
					count: remaining,
					sizeType: ['compressed'],
					sourceType: ['album', 'camera']
				});
				paths = (result && result.tempFilePaths) || [];
			} catch (error) {
				const message = String((error && (error.errMsg || error.message)) || '');
				if (!/cancel/i.test(message)) showRequestError(error, '选择照片失败');
				return;
			}
			if (!paths.length) return;

			this.uploading = true;
			try {
				const photos = [];
				for (let index = 0; index < paths.length; index += 1) {
					uni.showLoading({ title: `上传中 ${index + 1}/${paths.length}`, mask: true });
					const compressed = await uni.compressImage({
						src: paths[index],
						quality: 72,
						compressedWidth: 1280
					});
					const uploadPath = compressed && compressed.tempFilePath;
					if (!uploadPath) throw new Error('照片压缩失败。');

					const uploaded = await uploadImage(uploadPath);
					if (!uploaded || !uploaded.url) throw new Error('照片上传失败。');
					photos.push({
						url: uploaded.url,
						thumbnailUrl: uploaded.thumbnailUrl || uploaded.url
					});
				}
				this.applyAlbum(await addAlbumPhotos(photos));
				uni.showToast({ title: '照片已加入相册', icon: 'success' });
			} catch (error) {
				showRequestError(error, '照片上传失败');
			} finally {
				uni.hideLoading();
				this.uploading = false;
			}
		},
		handlePhotoClick(index) {
			if (this.managing) return;
			this.previewImage(index);
		},
		previewImage(index) {
			const urls = this.albumItems.map((item) => item.url);
			if (!urls.length) return;
			uni.previewImage({ current: urls[index], urls });
		},
		movePhoto(index, offset) {
			if (!this.managing) return;
			const targetIndex = index + offset;
			if (targetIndex < 0 || targetIndex >= this.albumItems.length) return;
			const nextItems = [...this.albumItems];
			const current = nextItems[index];
			nextItems.splice(index, 1);
			nextItems.splice(targetIndex, 0, current);
			this.albumItems = nextItems;
			this.orderDirty = true;
		},
		async toggleManage() {
			if (this.saving || this.uploading) return;
			if (!this.managing) {
				this.managing = true;
				this.orderDirty = false;
				return;
			}
			if (!this.orderDirty) {
				this.managing = false;
				return;
			}

			this.saving = true;
			try {
				const itemKeys = this.albumItems.map((item) => item.key);
				this.applyAlbum(await updateAlbumOrder(itemKeys));
				this.managing = false;
				uni.showToast({ title: '顺序已保存', icon: 'success' });
			} catch (error) {
				showRequestError(error, '顺序保存失败');
			} finally {
				this.saving = false;
			}
		},
		confirmDelete(item) {
			if (!item || item.type !== 'manual' || this.saving) return;
			uni.showModal({
				title: '删除照片',
				content: '这张手动上传的照片将从相册中删除。',
				confirmText: '删除',
				confirmColor: '#dc5b75',
				success: async (result) => {
					if (!result.confirm) return;
					this.saving = true;
					try {
						const pendingKeys = this.albumItems
							.filter((albumItem) => albumItem.key !== item.key)
							.map((albumItem) => albumItem.key);
						const hadPendingOrder = this.orderDirty;
						const album = await deleteAlbumPhoto(item.id);
						this.applyAlbum(album);
						if (hadPendingOrder) {
							const itemMap = new Map(this.albumItems.map((albumItem) => [albumItem.key, albumItem]));
							const pendingItems = pendingKeys.map((key) => itemMap.get(key)).filter(Boolean);
							const pendingSet = new Set(pendingKeys);
							this.albumItems = [
								...pendingItems,
								...this.albumItems.filter((albumItem) => !pendingSet.has(albumItem.key))
							];
							this.orderDirty = true;
						}
						this.managing = this.albumItems.length > 0;
						uni.showToast({ title: '照片已删除', icon: 'success' });
					} catch (error) {
						showRequestError(error, '照片删除失败');
					} finally {
						this.saving = false;
					}
				}
			});
		},
		leavePage() {
			const pages = getCurrentPages();
			if (pages.length > 1) {
				uni.navigateBack({
					fail: () => uni.switchTab({ url: '/pages/profile/index' })
				});
				return;
			}
			uni.switchTab({ url: '/pages/profile/index' });
		},
		goBack() {
			if (!this.managing || !this.orderDirty) {
				this.leavePage();
				return;
			}
			uni.showModal({
				title: '放弃排序？',
				content: '调整后的照片顺序还没有保存。',
				confirmText: '放弃',
				confirmColor: '#dc5b75',
				success: (result) => {
					if (result.confirm) this.leavePage();
				}
			});
		}
	}
};
</script>

<style lang="scss" scoped>
.album-page {
	min-height: 100vh;
	background: #f7f7f8;
}

.album-header {
	background: rgba(255, 255, 255, 0.98);
	border-bottom: 1rpx solid #eceaed;
}

.nav-bar {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 92rpx;
	padding: 0 24rpx;
}

.nav-side {
	display: flex;
	align-items: center;
	width: 112rpx;
}

.nav-side.is-right {
	justify-content: flex-end;
}

.nav-action {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 58rpx;
	height: 58rpx;
}

.back-icon {
	display: block;
	width: 34rpx;
	height: 34rpx;
}

.nav-title {
	position: absolute;
	left: 150rpx;
	right: 150rpx;
	color: #24232a;
	font-size: 31rpx;
	font-weight: 700;
	text-align: center;
}

.album-body {
	min-height: 100vh;
	box-sizing: border-box;
}

.album-tools {
	display: flex;
	align-items: center;
	justify-content: space-between;
	min-height: 112rpx;
	padding: 0 26rpx;
	background: #fff;
	border-bottom: 1rpx solid #eeecef;
}

.album-summary {
	display: flex;
	align-items: flex-start;
	justify-content: center;
	flex-direction: column;
	min-width: 0;
	flex: 1;
}

.summary-title,
.summary-count {
	display: block;
}

.summary-title {
	color: #312f35;
	font-size: 28rpx;
	font-weight: 650;
}

.summary-count {
	margin-top: 7rpx;
	color: #99949c;
	font-size: 21rpx;
}

.tool-actions {
	display: flex;
	align-items: center;
	justify-content: flex-end;
	gap: 10rpx;
	margin-left: 16rpx;
	flex-shrink: 0;
}

.manage-action {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 104rpx;
	height: 64rpx;
	box-sizing: border-box;
	border: 1rpx solid rgba(212, 104, 138, 0.48);
	border-radius: 8rpx;
	background: #fff7fa;
	color: #d4688a;
	font-size: 23rpx;
	font-weight: 600;
}

.manage-action.active {
	border-color: #d4688a;
	background: #d4688a;
	color: #fff;
}

.manage-action.disabled {
	opacity: 0.48;
}

.upload-action {
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 8rpx;
	min-width: 154rpx;
	height: 64rpx;
	box-sizing: border-box;
	padding: 0 20rpx;
	border-radius: 8rpx;
	color: #fff;
	font-size: 23rpx;
	font-weight: 600;
	background: linear-gradient(135deg, #c0527a, #d4688a);
	box-shadow: 0 7rpx 18rpx rgba(212, 104, 138, 0.22);
}

.upload-action.disabled {
	background: #e4b5c5;
	box-shadow: none;
	opacity: 0.68;
}

.upload-icon {
	display: block;
	width: 28rpx;
	height: 28rpx;
	font-size: 30rpx;
	font-weight: 400;
	line-height: 25rpx;
	text-align: center;
}

.album-grid {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 5rpx;
	padding: 5rpx;
}

.album-item {
	position: relative;
	width: 100%;
	aspect-ratio: 1;
	overflow: hidden;
	background: #e9e8ea;
}

.album-item.managing {
	outline: 1rpx solid rgba(255, 255, 255, 0.7);
}

.album-image {
	display: block;
	width: 100%;
	height: 100%;
}

.manage-shade {
	position: absolute;
	inset: 0;
	background: linear-gradient(to bottom, rgba(24, 22, 25, 0.36), transparent 38%, transparent 56%, rgba(24, 22, 25, 0.55));
}

.position-index {
	position: absolute;
	top: 9rpx;
	left: 10rpx;
	color: #fff;
	font-size: 21rpx;
	font-weight: 700;
	text-shadow: 0 1rpx 4rpx rgba(0, 0, 0, 0.35);
}

.delete-action {
	position: absolute;
	top: 8rpx;
	right: 8rpx;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 42rpx;
	height: 42rpx;
	border-radius: 50%;
	color: #fff;
	font-size: 32rpx;
	line-height: 1;
	background: rgba(197, 62, 88, 0.92);
}

.move-actions {
	position: absolute;
	left: 8rpx;
	right: 8rpx;
	bottom: 8rpx;
	display: flex;
	align-items: center;
	justify-content: space-between;
}

.move-action {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 50rpx;
	height: 42rpx;
	border-radius: 5rpx;
	color: #fff;
	font-size: 38rpx;
	line-height: 1;
	background: rgba(31, 29, 32, 0.7);
}

.move-action.disabled {
	opacity: 0.28;
}

.state-box {
	display: flex;
	align-items: center;
	justify-content: center;
	flex-direction: column;
	min-height: 570rpx;
	padding: 40rpx;
	text-align: center;
}

.empty-image {
	width: 210rpx;
	height: 210rpx;
	margin-bottom: 18rpx;
}

.state-title,
.state-copy,
.state-text {
	display: block;
}

.state-title {
	color: #56515a;
	font-size: 28rpx;
}

.state-copy,
.state-text {
	margin-top: 12rpx;
	color: #aaa5ad;
	font-size: 23rpx;
}
</style>
